import React, {FC} from 'react';
import "./Header.scss";

const Header: FC = () => {
    return (
        <header>
            <h1>Relationz</h1>
            <nav className={"navigation"}>
                <ul>
                    <li><link  href="/" className={`${location.pathname === '/' ? 'active' : ''}`}>Home</link></li>
                    <li><a href="/catalog">Catalog</a></li>
                    <li><a href="/">Cart</a></li>
                </ul>
            </nav>

        </header>
    );
};

export default Header;
